console = Console()


class SEVERITY(Enum):
    LOW = "Low"
    MEDIUM = "Medium"
    HIGH = "High"
    CRITICAL = "Critical"

class CVE(BaseModel):
    cve_id : str = Field(description="The CVE ID of the Vulnerability")
    description : str = Field(description="A detailed description of the Vulnerability")
    severity : SEVERITY = Field(description="The severity of the Vulnerability")

class Vulnerability(BaseModel):
    name : str = Field(description="The name of the Vulnerability")
    description : str = Field(description="A detailed description of the Vulnerability")
    code_snippet_or_location : str | None = Field(description="The code snippet or location of the Vulnerability , only return this if it is provided in the results , if not return None")
    cves : list[CVE] = Field(description="The list of CVE IDs for the Vulnerability")
    severity : SEVERITY = Field(description="The severity of the Vulnerability")
    fix : str = Field(description="The fix for the Vulnerability")

class ExportResults(BaseModel):
    vulnerabilities : list[Vulnerability] = Field(description="The list of Vulnerabilities found in the System overall")


   

